llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Pentazocine, the highest-transfer analogue, has a mean absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold, with the low value attributed to extensive first-pass metabolism; this is direct threshold-relevant evidence that a small lipophilic phenolic/enolic drug can have low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "In patients with cirrhosis, pentazocine's systemic availability rises to 70%, confirming that its low oral F is due to hepatic first-pass extraction rather than poor absorption; the query's 4-hydroxy-3-keto steroid is similarly prone to hepatic conjugation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Ethinylestradiol, a phenolic steroid, has an absolute oral bioavailability of 43 ± 16%, showing that phenolic steroids can exceed 20%; however, its 17α-ethinyl group blocks oxidative metabolism, a protective feature absent from the query's 17-ketone.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C39"],
      "claim": "Ursodeoxycholic acid shows 50% systemic availability in healthy subjects, but as a bile acid with enterohepatic circulation it is not a good model for the query's unprotected 4-hydroxy-3,17-dione steroid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The strongest transferable evidence (pentazocine, transfer 0.9786) directly shows F ≈ 18% in healthy subjects due to first-pass metabolism, and the query's enolic 4-hydroxy-3-keto-17-one steroid is expected to undergo extensive conjugation/reduction. High-F steroid analogues either have protective groups (ethinylestradiol) or different disposition (bile acids, cardiac glycosides), so low is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability record for the query molecule",
    "No steroid analogue with the exact 4-hydroxy-3-keto-17-one motif",
    "Human pharmacokinetic data for formestane would resolve uncertainty"
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

